import{z as i,x as n,o as e,c as d,q as t,j as B,D as E,d as A,s as o,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"可扩展监督","description":"","frontmatter":{"title":"可扩展监督","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/scalable-oversight.md","filePath":"llm/scalable-oversight.md","lastUpdated":1791413859000}'),p={name:"llm/scalable-oversight.md"};function h(m,a,D,c,f,P){const l=n("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="可扩展监督" tabindex="-1">可扩展监督 <a class="header-anchor" href="#可扩展监督" aria-label="Permalink to &quot;可扩展监督&quot;">​</a></h1><div class="epigraph"><p>监督者比被监督者弱，还要把反馈做到足够密、足够真；方案是协议，不是更大的奖励模型。</p><footer>—— Bowman 等 Measuring Progress on Scalable Oversight；Christiano 的放大与递归奖励模型；辩论与弱到强是子协议</footer></div><p><a href="/llm/weak-to-strong">上一课</a>给出一种测量：弱标签能否唤醒强表征。本课把辩论、过程监督、递归奖励、宪法、弱到强收成同一纲领——可扩展监督（scalable oversight）：<strong>人（或弱模型）的每小时注意力，如何监督更长、更强、更不可见的计算。</strong> 不重写 <a href="/llm/rlhf-pipeline">RLHF</a> 三阶段，只写第三阶段的反馈从哪放大。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>InstructGPT 假设标注员能判断两条回答谁更好。任务变长、模型变强、欺骗变可能时，这个假设坏掉。Christiano 的放大：把难题拆成子问题，人只解子问题，模型学组合。递归奖励模型：用当前助手帮助人训下一个奖励模型。辩论：人只看交锋。过程监督：人标步骤而不是终点。弱到强：承认标签弱，指望泛化。共同结构是协议 + 测量：在仍有金标的代理任务上，弱监督者借助协议后的准确率是否上升。</p><p>Bowman 等强调要测量，不要只讲故事。没有金标的「感觉更安全」不算进度。代理任务要预先锁死：一旦用辩论协议刷过同一套金标再报进步，那是过拟合协议，不是监督杠杆。<span class="marginnote">类比：老师改不动博士论文，但可以主持一场两名博士生对辩的答辩，只判谁被问住了。辩论协议押的就是「判对错比亲自做对容易」这个不对称。</span></p><h3 id="优化压力会摧毁监督通道" tabindex="-1">优化压力会摧毁监督通道 <a class="header-anchor" href="#优化压力会摧毁监督通道" aria-label="Permalink to &quot;优化压力会摧毁监督通道&quot;">​</a></h3><p>Baker、Korbak 等后来在推理模型上表明：把监视器写进奖励，链会变得看起来无害。可扩展监督的通道一旦进入 <a href="/llm/ppo-llm">PPO</a> 的 \\(r\\)，就会被 Goodhart。纲领里必须留<strong>不被直接优化</strong>的审计通道，或付 monitorability tax。<span class="marginnote">Goodhart 定律白话版：「一个指标一旦被当成目标，就不再是好指标」。在 RL 里它有精确含义：把代理指标写进 \\(r\\)，策略梯度会找到该指标的每一个漏洞并加以利用。</span></p><p><span class="marginnote">可扩展监督 ≠ 无人类。人设计协议、抽检金标、写宪法。扩大的是注意力杠杆，不是退出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选代理任务（有金标的难题）→ 选协议（辩论 / 逐步标 / 放大）→ 弱监督者 + 协议 vs 弱监督者独做 vs 强专家上限 → 报准确率与费用（人时、生成 token）。把胜出的协议接到 RL 时，另留一份协议外金标做过优化监控。与 <a href="/llm/verifiable-reward">可验证奖励</a> 的关系：能程序判定的不要用人协议；协议留给不可判定轴。</p>',11)),(e(),B(s,null,{default:E(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HUM%5B%22%E5%BC%B1%E7%9B%91%E7%9D%A3%E8%80%85%22%5D%20--%3E%20PROT%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E8%BE%A9%E8%AE%BA%20%2F%20%E6%94%BE%E5%A4%A7%20%2F%20%E8%BF%87%E7%A8%8B%22%5D%0A%20%20PROT%20--%3E%20SIG%5B%22%E6%9B%B4%E5%AF%86%E6%88%96%E6%9B%B4%E5%87%86%E7%9A%84%E5%8F%8D%E9%A6%88%22%5D%0A%20%20SIG%20--%3E%20RL%5B%22%E6%8E%A5%E5%88%B0%20PPO%20%2F%20DPO%22%5D%0A%20%20RL%20--%3E%20RISK%5B%22%E4%BC%98%E5%8C%96%E5%8E%8B%E5%9E%AE%E9%80%9A%E9%81%93%22%5D%0A%20%20GOLD%5B%22%E5%8D%8F%E8%AE%AE%E5%A4%96%E9%87%91%E6%A0%87%22%5D%20--%3E%20MON%5B%22%E8%BF%87%E4%BC%98%E5%8C%96%E7%9B%91%E6%8E%A7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[A("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"杠杆来自分解：局部更容易核对（过程、引用、子问题）。失败来自合成：模型在分解缝隙里作弊，或协议被修辞填满。弱到强提供另一杠杆：预训练知识纠噪声。两者可叠加：协议提高相关，泛化吃掉剩余噪声。没有银弹。",-1)),(e(),B(s,null,{default:E(()=>[o(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E8%BF%87%E7%A8%8B%E7%9B%91%E7%9D%A3%3A%20%E4%BA%BA%E6%A0%87%E6%AF%8F%E4%B8%80%E6%AD%A5%22%5D%20--%3E%20L1%5B%22%E6%9D%A0%E6%9D%86%3A%20%E5%B1%80%E9%83%A8%E7%BB%93%E8%AE%BA%E6%98%93%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20P1%20--%3E%20F1%5B%22%E5%A4%B1%E8%B4%A5%3A%20%E6%AD%A5%E6%AD%A5%E5%AF%B9%2C%20%E5%90%88%E6%88%90%E4%BB%8D%E5%8F%AF%E9%94%99%22%5D%0A%20%20P2%5B%22%E6%94%BE%E5%A4%A7%3A%20%E6%8B%86%E6%88%90%E5%AD%90%E9%97%AE%E9%A2%98%22%5D%20--%3E%20L2%5B%22%E6%9D%A0%E6%9D%86%3A%20%E4%BA%BA%E5%8F%AA%E8%A7%A3%E5%B0%8F%E9%A2%98%22%5D%0A%20%20P2%20--%3E%20F2%5B%22%E5%A4%B1%E8%B4%A5%3A%20%E6%A8%A1%E5%9E%8B%E5%9C%A8%E7%BC%9D%E9%9A%99%E9%87%8C%E4%BD%9C%E5%BC%8A%22%5D%0A%20%20P3%5B%22%E5%BC%B1%E5%88%B0%E5%BC%BA%3A%20%E5%BC%B1%E6%A0%87%E7%AD%BE%E5%94%A4%E9%86%92%E5%BC%BA%E8%A1%A8%E5%BE%81%22%5D%20--%3E%20L3%5B%22%E6%9D%A0%E6%9D%86%3A%20%E9%A2%84%E8%AE%AD%E7%BB%83%E6%B3%9B%E5%8C%96%E5%90%83%E5%99%AA%E5%A3%B0%22%5D%0A%20%20P3%20--%3E%20F3%5B%22%E5%A4%B1%E8%B4%A5%3A%20%E5%BC%B1%E6%A0%87%E7%AD%BE%E5%81%8F%E7%BD%AE%E8%A2%AB%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">递归 RM 会把上一代的黑客写进下一代奖励，错误复合。必须隔代用人类校准。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>近期产品仍以人类比较 + 校验器 + 宪法为主，可扩展监督是研究与前沿实验室的规划语言。下一课把宪法式 RL 写成已经落地的实践，而不是纯协议思想。安全拒绝、诚实校准是监督目标的两个具体轴。</p><p>协议一旦写进奖励就会被优化掉。测量必须在代理任务上、并另留协议外金标，否则只是更贵的 RLHF。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可扩展监督研究弱监督者如何借助协议监督强计算，必须在代理任务上测量。</li><li>子协议：放大、递归 RM、辩论、过程监督、弱到强。</li><li>通道一旦进入奖励就会被优化掉，需协议外金标。</li><li>能校验器解决的轴不要用人协议。</li><li>出处：Bowman 等；Christiano 放大 / 递归 RM；Irving 辩论；Burns 弱到强；Lightman PRM。</li></ul>',6))])}const b=i(p,[["render",h]]);export{C as __pageData,b as default};
